@extends('layouts.admin') @section('content')<main class="admin-profile p-5 lg:p-8"><a class="text-sm text-sky-600" href="{{ route('admin.certificates.index') }}">← Certificates</a><h1 class="mt-4 text-4xl font-bold">{{ $certificate->exists ? 'Edit' : 'Add' }} certificate</h1><form method="POST" action="{{ $action }}" enctype="multipart/form-data" class="admin-card mt-8 grid gap-5 p-6 md:grid-cols-2">@csrf @if($certificate->exists) @method('PUT') @endif @foreach([['title','Title','text'],['issuer','Issuer','text'],['issue_date','Issue date','date'],['credential_id','Credential ID','text'],['url','Credential URL','url'],['sort_order','Sort order','number']] as [$field,$label,$type])<label class="text-sm">{{ $label }}<input name="{{ $field }}" type="{{ $type }}" value="{{ old($field,$certificate->{$field}) }}" class="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3"></label>@endforeach<label class="text-sm">Certificate image<input id="certificate-image" type="file" name="image_path" accept="image/*" class="mt-2 block"></label><div id="certificate-preview" class="h-32 rounded-xl bg-slate-100">@if($certificate->image_path)<img src="{{ asset('storage/'.$certificate->image_path) }}" class="h-full w-full object-contain" alt="Certificate preview">@endif</div><button class="w-fit rounded-lg bg-sky-500 px-5 py-3 font-semibold text-white">Save certificate</button></form><script>document.getElementById('certificate-image')?.addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=x=>document.getElementById('certificate-preview').innerHTML='<img src="'+x.target.result+'" class="h-full w-full object-contain" alt="Selected certificate">';r.readAsDataURL(f)});</script></main>@endsection
